import './index.less'

// 阳台光伏 banner
export default class PhotovolaticBanner {
  constructor({ swiperContainer }) {
    this.DOM = document.querySelector(swiperContainer)
    if (this.DOM) {
      const { loop, autoplay, autoplayDelay, size, } = this.DOM?.dataset
      this.config = {
        loop: size > 1 ? loop === 'true' : false,
        autoplay: autoplay === 'true',
        autoplayDelay,
      }
      this.DOM.querySelectorAll('.swiper-balcony-banner-text').forEach(item => item.style.opacity = 1)
      this.init(swiperContainer)
    }
  }
  init(swiperContainer) {
    const interleaveOffset = 0.5; // 视差比值
    new Swiper(swiperContainer, {
      autoplay: this.config.autoplay ? {
        delay: this.config.autoplayDelay * 1000,
        disableOnInteraction: false
      } : false,
      keyboard: true,
      loop: this.config.loop,
      speed: 500,
      preloadImages: true,
      updateOnImagesReady: true,
      watchSlidesProgress: true,
      watchSlidesVisibility: true,
      observer: true, // 开启动态检查器，监测swiper和slide
      observeParents: true, // 监测Swiper 的祖/父元素
      lazy: {
        loadPrevNext: true,
        loadPrevNextAmount: 1
      },
      navigation: {
        enabled: false
      },
      pagination: {
        el: '.swiper-balcony-pagination',
        clickable: true,
        bulletClass: 'swiper-balcony-pagination-bullet',
        bulletActiveClass: 'swiper-balcony-pagination-bullet-active',
        clickableClass: 'swiper-balcony-pagination-clickable',
        modifierClass: 'swiper-balcony-pagination-',
        renderBullet: function(index, className) {
          return `<span class="${className}"></span>`
        }
      },
      on: {
        progress: function(swiper) {
          for (var i = 0; i < swiper.slides.length; i++) {
            var slideProgress = swiper.slides[i].progress;
            var innerOffset = swiper.width * interleaveOffset;
            var innerTranslate = slideProgress * innerOffset;
            swiper
              .slides[i]
              .querySelector(".slide-inner")
              .style
              .transform = "translate3d(" + innerTranslate + "px, 0, 0)";
          }
        },
        touchStart: function(swiper) {
          for (var i = 0; i < swiper.slides.length; i++) {
            swiper.slides[i].style.transition = "";
          }
        },
        setTransition: function(swiper, speed) {
          for (var i = 0; i < swiper.slides.length; i++) {
            swiper.slides[i].style.transition = speed + "ms";
            swiper
              .slides[i]
              .querySelector(".slide-inner")
              .style
              .transition = speed + "ms";
          }
        },
        slideChangeTransitionEnd: function () {
          const curSlide = Array.from(this.slides).filter(it => it.classList.contains('swiper-slide-active'))
          const curImg = $(curSlide).find('img')[0]
          // 播放当前视频
          if (curImg) {
            curImg.classList.remove('lazyloading')
            curImg.classList.add('lazyloaded')
          }
        },
        resize: function() {
          setTimeout(() => {
            this.update(); // 窗口变化时，更新Swiper的一些属性，如宽高等
          }, 500)
        }
      }
    })
  }
}
