import './index.less'

export default class PhotovolaticForBalcony {
    constructor({ wrapEl, pcEl, mbEl }) {
        this.wrapDOM = document.querySelector(wrapEl)
        this.PCDOM = document.querySelector(pcEl)
        this.MBDOM = document.querySelector(mbEl)
        this.mbEl = mbEl

        if (this.PCDOM && this.MBDOM) {
            this.init()

            this.init = this.init.bind(this)
            window.addEventListener('resize', this.init)
        }

        this.wrapDOM && this.observe()
    }
    init() {
        const clientWidth = document.documentElement.clientWidth || document.body.clientWidth
        if (clientWidth < 1024) {
            this.MBDOM.classList.remove('hidden')
            this.PCDOM.classList.add('!hidden')

            if (!this.swiperMB) {
                this.MBDOM && this.initMB();
            }

            // resize 时清除
            this.swiperPC?.destroy();
            this.swiperPC2?.destroy();
            this.swiperPC = null;
            this.swiperPC2 = null;
        } else {
            this.MBDOM.classList.add('hidden')
            this.PCDOM.classList.remove('!hidden')

            if (!this.swiperPC && !this.swiperPC2) {
                this.PCDOM && this.initPC();
            }

            // resize 时清除
            this.swiperMB?.destroy();
            this.swiperMB = null;
        }

        // 数据埋码
        document.querySelectorAll('[data-for-balcony-link]').forEach(item => {
            item.onclick = (e) => {
                const { sectionTitle, productTitle, buttonText, buttonLink, } = e.target.dataset
                this.GAEvent({
                    module: sectionTitle,
                    position: productTitle,
                    button_name: buttonText,
                    link: buttonLink,
                })
            }
        })
    }
    initPC() {
        const { autoplay, autoplayDelay, size, } = this.PCDOM?.dataset
        this.config = {
            loop: size > 1 ? true : false,
            autoplay: autoplay === 'true',
            autoplayDelay,
        }

        this.swiperPC = new Swiper(".swiper-thumbs-small-images", {
            spaceBetween: 0,
            slidesPerView: 4,
            freeMode: true,
            direction: "vertical",
            loop: false,
        })
        this.swiperPC2 = new Swiper(".swiper-main-content-images", {
            autoplay: this.config.autoplay ? {
                delay: this.config.autoplayDelay * 1000,
                disableOnInteraction: false
            } : false,
            spaceBetween: 80,
            direction: "vertical",
            loop: this.config.loop,
            preloadImages: true,
            updateOnImagesReady: true,
            watchSlidesProgress: true,
            watchSlidesVisibility: true,
            observer: true, // 开启动态检查器，监测swiper和slide
            observeParents: true, // 监测Swiper 的祖/父元素
            lazy: {
                loadPrevNext: true,
                loadPrevNextAmount: 1
            },
            thumbs: {
                swiper: this.swiperPC,
            },
            on: {
                slideChangeTransitionEnd: function () {
                    const curSlide = Array.from(this.slides).filter(it => it.classList.contains('swiper-slide-active'))
                    const curImg = $(curSlide).find('img')[0]
                    // 播放当前视频
                    if (curImg) {
                      curImg.classList.remove('lazyloading')
                      curImg.classList.add('lazyloaded')
                    }
                },
            }
        })
    }
    initMB() {
        this.swiperMB = new Swiper(this.mbEl, {
            autoplay: false,
            autoHeight: true,
            spaceBetween: 20,
            loop: true,
            preloadImages: true,
            updateOnImagesReady: true,
            watchSlidesProgress: true,
            watchSlidesVisibility: true,
            observer: true, // 开启动态检查器，监测swiper和slide
            observeParents: true, // 监测Swiper 的祖/父元素
            lazy: {
                loadPrevNext: true,
                loadPrevNextAmount: 1
            },
            navigation: {
                nextEl: '.swiper-photovolatic-button-next',
                prevEl: '.swiper-photovolatic-button-prev',
            },
            pagination: {
                el: ".swiper-photovolatic-pagination",
                clickable: true,
                renderBullet: function (index, className) {
                    return '<span class="' + className + '">' + (index + 1) + "</span>";
                },
            },
            on: {
                slideChangeTransitionEnd: function () {
                    const curSlide = Array.from(this.slides).filter(it => it.classList.contains('swiper-slide-active'))
                    const curImg = $(curSlide).find('img')[0]
                    // 播放当前视频
                    if (curImg) {
                      curImg.classList.remove('lazyloading')
                      curImg.classList.add('lazyloaded')
                    }
                },
            }
        })
    }
    observe() {
        const clientWidth = document.documentElement.clientWidth || document.body.clientWidth

        // 视频进入视口监听播放
        const Observer = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    // PC
                    if (clientWidth >= 1024 && this.config.autoplay) {
                        this.swiperPC2?.autoplay?.start()
                    }
                } else {
                    // PC
                    if (clientWidth >= 1024 && this.config.autoplay) {
                        this.swiperPC2?.autoplay?.stop()
                    }
                }
            })
        }, {
            root: null,
            rootMargin: '0px',
            threshold: 0.25, // 设置阈值为80%，即视频可见面积超过50%触发播放
        })

        Observer.observe(this.wrapDOM)
    }

    // 数据埋码
    GAEvent(params) {
        window.dataLayer.push({ "event_parameters": null });
        window.dataLayer.push({
            "event":"ga4Event",
            "event_name":"photovoltaics_user_clicks",
            "event_parameters":{
                "current_page": window.location.href, // current page url
                ...params
            }
        });
    }
}
