import './index.less'

import './sections/photovolatic-more-service/index.less'

import PhotovolaticBanner from "./sections/photovolatic-banner"
import PhotovolaticForHome from "./sections/photovolatic-for-home"
import PhotovolaticScenes from "./sections/photovolatic-scenes"
import PhotovolaticProduct from "./sections/photovolatic-product"
import PhotovolaticWhyChoose from "./sections/photovolatic-why-choose"
import PhotovolaticForBalcony from "./sections/photovolatic-for-balcony"
import PhotovolaticSetup from "./sections/photovolatic-setup"
import PhotovolaticUserGuide from "./sections/photovolatic-user-guide"
import PhotovolaticFindOut from "./sections/photovolatic-find-out"
import PhotovolaticCommentList from "./sections/photovolatic-comment-list"

import IndexSupport from './sections/index-support'



document.addEventListener('DOMContentLoaded', () => {
  // Banner
  new PhotovolaticBanner({ swiperContainer: ".swiper-balcony-banner", })

  // for home
  new PhotovolaticForHome({ el: '.balcony-scale-img-wrap' })

  // scenes
  new PhotovolaticScenes({
    pcEl: '.swiper-balcony-tab-content-pc',
    mbEl: '.swiper-balcony-tab-content-mb'
  })

  // two product
  new PhotovolaticProduct()

  // why choose
  new PhotovolaticWhyChoose({
    wrapEl: '.photovolatic-why-choose-wrap',
    pcEl: '.swiper-balcony-tab-vs-pc',
    mbEl: '.swiper-balcony-tab-vs-mb'
  })

  // for balcony
  new PhotovolaticForBalcony({
    wrapEl: '.photovolatic-for-balcony-wrap',
    pcEl: '.swiper-left-right-wrap',
    mbEl: '.swiper-main-content-mb'
  })

  // set-up
  new PhotovolaticSetup({ el: '.photovolatic-setup-wrap' })

  // user-guide
  new PhotovolaticUserGuide({ el: '.photovolatic-user-guide-wrap' })

  // FindOut 红人视频
  new PhotovolaticFindOut({
    pcEl: ".findout-pc-swiper",
    mbEl: ".findout-mb-swiper",
  })

  // 案例推荐
  new PhotovolaticCommentList({
    pcEl: ".commentlist-pc-swiper",
    mbEl: ".commentlist-mb-swiper",
  })

  IndexSupport()
})
