import './index.less'

export default class PhotovolaticWhyChoose {
    constructor({ wrapEl, pcEl, mbEl }) {
        this.wrapDOM = document.querySelector(wrapEl)
        this.PCDOM = document.querySelector(pcEl)
        this.MBDOM = document.querySelector(mbEl)
        this.pcEl = pcEl
        this.mbEl = mbEl

        // tab items/deco
        this.tabItems = document.querySelectorAll('[data-balcony-tab-vs-item]')
        this.tabDeco = document.querySelector('[data-balcony-tab-vs-deco]')

        if (this.PCDOM && this.MBDOM) {
            this.init()
            // 初始化 deco 宽度
            this.tabDeco.style.width = this.tabItems[0].offsetWidth + 'px'

            this.resize = this.resize.bind(this)
            window.addEventListener('resize', this.resize)
        }

        this.wrapDOM && this.observe()
    }
    init() {
        const clientWidth = document.documentElement.clientWidth || document.body.clientWidth
        if (clientWidth < 1024) {
            this.MBDOM.classList.remove('hidden')
            this.PCDOM.parentElement.classList.add('hidden')
            this.MBDOM && this.initMB()
        } else {
            this.MBDOM.classList.add('hidden')
            this.PCDOM.parentElement.classList.remove('hidden')
            this.PCDOM && this.initPC()
        }
    }
    initPC() {
        this.tabItems.forEach((item, index) => {
            item.onclick = () => {
                this.tabItems.forEach(t => t.classList.remove('balcony-tab-vs-active'))
                item.classList.add('balcony-tab-vs-active')

                this.tabDeco.style.width = item.offsetWidth + 'px'
                this.tabDeco.style.left = item.offsetLeft + 'px'

                this.swiperPC.slideToLoop(index, 300, false);
            }
        })

        const { autoplay, autoplayDelay, size, } = this.PCDOM?.dataset
        this.config = {
            loop: size > 1 ? true : false,
            autoplay: autoplay === 'true',
            autoplayDelay,
        }

        const self = this
        this.swiperPC = new Swiper(this.pcEl, {
            autoplay: this.config.autoplay ? {
                delay: this.config.autoplayDelay * 1000,
                disableOnInteraction: false
            } : false,
            slidesPerView: 1,
            spaceBetween: 20,
            centeredSlides: true,
            loop: this.config.loop,
            initialSlide: 0,
            preloadImages: true,
            updateOnImagesReady: true,
            watchSlidesProgress: true,
            watchSlidesVisibility: true,
            observer: true, // 开启动态检查器，监测swiper和slide
            observeParents: true, // 监测Swiper 的祖/父元素
            lazy: {
                loadPrevNext: true,
                loadPrevNextAmount: 1
            },
            navigation: {
                nextEl: ".swiper-tab-vs-pc-button-next",
                prevEl: ".swiper-tab-vs-pc-button-prev",
            },
            on: {
                slideChangeTransitionStart: function () {
                    self.tabDeco.style.width = self.tabItems[this.realIndex].offsetWidth + 'px'
                    self.tabDeco.style.left = self.tabItems[this.realIndex].offsetLeft + 'px'

                    self.tabItems.forEach(t => t.classList.remove('balcony-tab-vs-active'))
                    self.tabItems[this.realIndex].classList.add('balcony-tab-vs-active')
                },
                slideChangeTransitionEnd: function () {
                    const curSlide = Array.from(this.slides).filter(it => it.classList.contains('swiper-slide-active'))
                    const curImg = $(curSlide).find('img')[0]
                    // 播放当前视频
                    if (curImg) {
                      curImg.classList.remove('lazyloading')
                      curImg.classList.add('lazyloaded')
                    }
                },
            }
        });
    }
    initMB() {
        this.swiperMB = new Swiper(this.mbEl, {
            autoplay: false,
            autoHeight: true,
            spaceBetween: 20,
            loop: true,
            preloadImages: true,
            updateOnImagesReady: true,
            watchSlidesProgress: true,
            watchSlidesVisibility: true,
            observer: true, // 开启动态检查器，监测swiper和slide
            observeParents: true, // 监测Swiper 的祖/父元素
            lazy: {
                loadPrevNext: true,
                loadPrevNextAmount: 1
            },
            navigation: {
                nextEl: '.swiper-tab-vs-button-next',
                prevEl: '.swiper-tab-vs-button-prev',
            },
            pagination: {
                el: ".swiper-tab-pagination",
                clickable: true,
                renderBullet: function (index, className) {
                    return '<span class="' + className + '">' + (index + 1) + "</span>";
                },
            },
            on: {
                slideChangeTransitionEnd: function () {
                    const curSlide = Array.from(this.slides).filter(it => it.classList.contains('swiper-slide-active'))
                    const curImg = $(curSlide).find('img')[0]
                    // 播放当前视频
                    if (curImg) {
                      curImg.classList.remove('lazyloading')
                      curImg.classList.add('lazyloaded')
                    }
                },
            }
        })
    }
    resize() {
        this.tabItems.forEach(item => {
            if (item.classList.contains('balcony-tab-vs-active')) {
                this.tabDeco.style.width = item.offsetWidth + 'px'
                this.tabDeco.style.left = item.offsetLeft + 'px'
            }
        })

        const clientWidth = document.documentElement.clientWidth || document.body.clientWidth
        if (clientWidth < 1024) {
            this.MBDOM.classList.remove('hidden')
            this.PCDOM.parentElement.classList.add('hidden')

            !this.swiperMB && this.initMB();

            this.swiperPC?.destroy();
            this.swiperPC = null;
        } else {
            this.MBDOM.classList.add('hidden')
            this.PCDOM.parentElement.classList.remove('hidden')

            if (!this.swiperPC) {
                // 初始化 deco 宽度
                this.tabDeco.style.width = this.tabItems[0].offsetWidth + 'px'
                this.PCDOM && this.initPC();
            }

            this.swiperMB?.destroy();
            this.swiperMB = null;
        }
    }
    observe() {
        const clientWidth = document.documentElement.clientWidth || document.body.clientWidth

        // 视频进入视口监听播放
        const Observer = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    // PC
                    if (clientWidth >= 1024 && this.config.autoplay) {
                        this.swiperPC?.autoplay?.start()
                    }
                } else {
                    // PC
                    if (clientWidth >= 1024 && this.config.autoplay) {
                        this.swiperPC?.autoplay?.stop()
                    }
                }
            })
        }, {
            root: null,
            rootMargin: '0px',
            threshold: 0.25, // 设置阈值为80%，即视频可见面积超过50%触发播放
        })

        Observer.observe(this.wrapDOM)
    }
}
