import './index.less'

export default class PhotovolaticScenes {
  constructor({ pcEl, mbEl }) {
    this.PCDOM = document.querySelector(pcEl)
    this.MBDOM = document.querySelector(mbEl)
    this.pcEl = pcEl
    this.mbEl = mbEl

    // tab items/deco
    this.tabItems = document.querySelectorAll('[data-balcony-tab-item]')
    this.tabDeco = document.querySelector('[data-balcony-tab-deco]')
    let splits = pcEl.split(' ')
    if (splits.length > 1) {
      this.tabItems = document.querySelectorAll(splits[0] + ' [data-balcony-tab-item]')
      this.tabDeco = document.querySelector(splits[0] + ' [data-balcony-tab-deco]')
    }

    // 当前播放视频的索引
    this.curIndex = 0

    if (this.PCDOM && this.MBDOM) {
      // 移动端是否平铺展开
      this.mobileExpand = this.MBDOM?.dataset?.expand === 'true'

      this.init()
      // 初始化 deco 宽度
      this.tabDeco.style.width = this.tabItems[0].offsetWidth + 'px'

      // 修正 this 指向，方便新增和移除事件
      this.videoEndedPlayEvent = this.videoEndedPlayEvent.bind(this)
      this.resize = this.resize.bind(this)

      window.addEventListener('resize', this.resize)
    }
  }
  init() {
    const clientWidth = document.documentElement.clientWidth || document.body.clientWidth
    if (clientWidth < 1024) {
      this.MBDOM?.classList?.remove('hidden')
      this.PCDOM.parentElement.classList.add('hidden')

      // Mobile Swiper 初始化
      if (!this.mobileExpand) {
        this.MBDOM && this.initMB()
      }

      this.checkMp4(this.MBDOM)
    } else {
      this.MBDOM?.classList?.add('hidden')
      this.PCDOM.parentElement.classList.remove('hidden')

      this.PCDOM && this.initPC()
    }
  }
  initPC() {
    this.tabItems.forEach((item, index) => {
      item.onclick = (e) => {
        this.tabItems.forEach(t => t.classList.remove('balcony-tab-active'))
        item.classList.add('balcony-tab-active')

        this.tabDeco.style.width = item.offsetWidth + 'px'
        this.tabDeco.style.left = item.offsetLeft + 'px'

        this.swiperPC.slideToLoop(index, 300, true);
      }
    })

    const self = this
    this.swiperPC = new Swiper(this.pcEl, {
      slidesPerView: 'auto',
      spaceBetween: 20,
      centeredSlides: true,
      loop: true,
      navigation: {
        nextEl: `${this.pcEl} .swiper-tab-pc-button-next`,
        prevEl: `${this.pcEl} .swiper-tab-pc-button-prev`,
      },
      on: {
        init: function () {
          // 获取所有幻灯片的高度
          let slideHeights = []
          this.slides.forEach(item => slideHeights.push(item.offsetHeight))

          // 找到最高的幻灯片高度
          const maxHeight = Math.max.apply(null, slideHeights)

          // 将 Swiper 容器的高度设置为最高的幻灯片高度
          self.PCDOM.style.height = `${maxHeight}px`
        },
        slideChangeTransitionStart: function () {
          self.tabDeco.style.width = self.tabItems[this.realIndex].offsetWidth + 'px'
          self.tabDeco.style.left = self.tabItems[this.realIndex].offsetLeft + 'px'

          // 暂停全部视频
          this.slides.each(function (slide) {
            const video = $(slide).find('jky-video')[0]
            if (video && video.pause) {
              video.videoInfo.autoplay = false
              video.pause()
            }
          })
        },
        slideChangeTransitionEnd: function () {
          const curSlide = Array.from(this.slides).filter(it => it.classList.contains('swiper-slide-active'))
          const curVideo = $(curSlide).find('jky-video')[0]

          self.playVideo('PC', curSlide, curVideo, false)
        },
      }
    });

    this.checkMp4(this.PCDOM)
  }
  initMB() {
    const self = this
    this.swiperMB = new Swiper(this.mbEl, {
      autoHeight: true,
      spaceBetween: 20,
      loop: true,
      navigation: {
        nextEl: `${this.mbEl} .swiper-balcony-tab-button-next`,
        prevEl: `${this.mbEl} .swiper-balcony-tab-button-prev`,
      },
      pagination: {
        el: `${this.mbEl} .swiper-tab-pagination`,
        clickable: true,
        renderBullet: function (index, className) {
          return '<span class="' + className + '">' + (index + 1) + "</span>";
        },
      },
      on: {
        slideChangeTransitionStart: function () {
          // 暂停全部视频
          this.slides.each(function (slide) {
            const video = $(slide).find('jky-video')[0]
            if (video && video.pause) {
              video.videoInfo.autoplay = false
              video.pause()
            }
          })
        },
        slideChangeTransitionEnd: function () {
          const curSlide = Array.from(this.slides).filter(it => it.classList.contains('swiper-slide-active'))
          const curVideo = $(curSlide).find('jky-video')[0]

          self.playVideo('MB', curSlide, curVideo, false)
        },
      }
    })
  }
  resize() {
    this.tabItems.forEach(item => {
      if (item.classList.contains('balcony-tab-active')) {
        this.tabDeco.style.width = item.offsetWidth + 'px'
        this.tabDeco.style.left = item.offsetLeft + 'px'
      }
    })

    const clientWidth = document.documentElement.clientWidth || document.body.clientWidth
    if (clientWidth < 1024) {
      this.MBDOM?.classList?.remove('hidden')
      this.PCDOM.parentElement.classList.add('hidden')

      if (!this.mobileExpand && !this.swiperMB) {
        this.MBDOM && this.initMB()
      }

      this.checkMp4(this.MBDOM)

      this.swiperPC?.destroy()
      this.swiperPC = null
    } else {
      this.MBDOM?.classList?.add('hidden')
      this.PCDOM.parentElement.classList.remove('hidden')

      if (!this.swiperPC) {
        // 初始化 deco 宽度
        this.tabDeco.style.width = this.tabItems[0].offsetWidth + 'px'
        this.PCDOM && this.initPC()
      }

      this.swiperMB?.destroy()
      this.swiperMB = null
    }
  }
  playVideo(type, curSlide, curVideo, autoPlay) {
    if (curVideo && curVideo.loadContent) {
      curVideo.videoInfo.autoplay = true
      curVideo.loadContent(false)

      // video
      if (curVideo.querySelector('video')) {
        // 如果最初加载失败，尝试重新加载视频
        if (curVideo.querySelector('video').networkState === HTMLMediaElement.NETWORK_NO_SOURCE) {
          curVideo.querySelector('video').load()
        }

        if (this.isAllMp4 && autoPlay) {
          // 监听视频播放完成事件
          curVideo.querySelector('video').addEventListener('ended', this.videoEndedPlayEvent)
        }

        // 监听 video 播放
        curVideo.querySelector('video').addEventListener('play', () => {
          // 数据埋码
          const { videoUrl, pcImageUrl, mbImageUrl, index, } = $(curSlide)[0].dataset
          this.GAEvent({
            position: videoUrl ? 'video' : 'picture',
            button_name: Number(index) + 1,
            link: videoUrl || (type === 'PC' ? pcImageUrl : mbImageUrl),
          })
        })
      } 
      // youtube 或者是 图片
      else {
        // 数据埋码
        const { videoUrl, pcImageUrl, mbImageUrl, index, } = $(curSlide)[0].dataset
        this.GAEvent({
          position: videoUrl ? 'video' : 'picture',
          button_name: Number(index) + 1,
          link: videoUrl || (type === 'PC' ? pcImageUrl : mbImageUrl),
        })
      }
    }
  }
  pauseVideo(curVideo) {
    if (curVideo && curVideo.pause) {
      curVideo.videoInfo.autoplay = false
      curVideo.pause()
    }
  }
  // 视频播放完成事件
  videoEndedPlayEvent() {
    this.curIndex++
    if (this.swiperPC) {
      this.swiperPC.slideToLoop(this.curIndex, 300, true)

      const curSlide = this.PCDOM.querySelector('.swiper-slide-active')
      const curVideo = $(curSlide).find('jky-video')[0]
      this.playVideo('PC', curSlide, curVideo, true)
    } else {
      this.playVideo('MB', this.jkyVideos[this.curIndex].parentElement, this.jkyVideos[this.curIndex], true)
    }
  }
  checkMp4(DOM) {
    this.jkyVideos = DOM.querySelectorAll('jky-video')

    // 是否都配置的 mp4 格式的视频
    const mp4Video = Array.from(this.jkyVideos).filter(item => item.getAttribute('video-type') === 'mp4')
    this.isAllMp4 = mp4Video.length === this.jkyVideos.length

    this.observe()
  }
  observe() {
    const clientWidth = document.documentElement.clientWidth || document.body.clientWidth

    // 视频进入视口监听播放
    const Observer = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          // Mobile, 播放第一个视频
          if (clientWidth < 1024) {
            if (this.curIndex !== this.tabItems.length - 1) {
              const curSlide = this.mobileExpand ? this.mbEl : this.MBDOM.querySelector('.swiper-slide-active')
              const index = this.mobileExpand ? this.curIndex : 0
              const curVideo = $(curSlide).find('jky-video')[index]
              this.playVideo('MB', curSlide, curVideo, true)
            }
          }
          // PC, 播放第一个视频
          else {
            if (this.curIndex !== this.tabItems.length - 1) {
              const curSlide = this.PCDOM.querySelector('.swiper-slide-active')
              const curVideo = $(curSlide).find('jky-video')[0]
              this.playVideo('PC', curSlide, curVideo, true)
            }
          }
        } else {
          // 暂停播放
          if (clientWidth < 1024) {
            const curDOM = this.mobileExpand ? this.mbEl : this.MBDOM.querySelector('.swiper-slide-active')
            const index = this.mobileExpand ? this.curIndex : 0
            const curVideo = $(curDOM).find('jky-video')[index]
            this.pauseVideo(curVideo)

            if (this.isAllMp4) {
              // 移除当前视频播放完成事件
              curVideo && curVideo.querySelector('video')?.removeEventListener('ended', this.videoEndedPlayEvent)
            }
          } else {
            const curSlide = this.PCDOM.querySelector('.swiper-slide-active')
            const curVideo = $(curSlide).find('jky-video')[0]
            this.pauseVideo(curVideo)

            if (this.isAllMp4) {
              // 移除当前视频播放完成事件
              curVideo && curVideo.querySelector('video')?.removeEventListener('ended', this.videoEndedPlayEvent)
            }
          }
        }
      })
    }, {
      root: null,
      rootMargin: '0px',
      threshold: 0.25,
    })

    Observer.observe(this.PCDOM.parentElement.parentElement)
  }

  // 数据埋码
  GAEvent(params) {
    window.dataLayer.push({ "event_parameters": null });
    window.dataLayer.push({
      "event":"ga4Event",
      "event_name":"photovoltaics_user_clicks",
      "event_parameters":{
        "current_page": window.location.href, // current page url
        "module": "Mul_tap Display",
        ...params
      }
    });
  }
}
