import './index.less'

export default class PhotovolaticUserGuide {
  constructor({ el }) {
    this.DOM = document.querySelector(el)
    this.el = el

    this.DOM && this.observe()
  }
  observe() {
    // 视频进入视口监听播放
    const Observer = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          // 播放当前视频
          const curVideo = $(this.el).find('jky-video')[0];
          if (curVideo && curVideo.loadContent) {
            curVideo.videoInfo.autoplay = true
            curVideo.loadContent(false)

            // 监听 video 播放
            curVideo.querySelector('video').addEventListener('play', () => {
              // 数据埋码
              const { sectionTitle, videoUrl, } = curVideo.parentElement.dataset
              this.GAEvent({
                module: sectionTitle,
                link: videoUrl,
              })
            })
          }
        } else {
          // 暂停播放
          const curVideo = $(this.el).find('jky-video')[0];
          if (curVideo && curVideo.pause) {
            curVideo.videoInfo.autoplay = false
            curVideo.pause()
          }
        }
      })
    },{
      root: null,
      rootMargin: '0px',
      threshold: 0.25, // 设置阈值为80%，即视频可见面积超过50%触发播放
    })

    Observer.observe(this.DOM)
  }

  // 数据埋码
  GAEvent(params) {
    window.dataLayer.push({ "event_parameters": null });
    window.dataLayer.push({
        "event":"ga4Event",
        "event_name":"photovoltaics_user_clicks",
        "event_parameters":{
            "current_page": window.location.href, // current page url
            ...params
        }
    });
  }
}

